#include <algorithm>
#include <string>
#include <vector>
std::vector<std::string>
byLength(std::vector<std::string> values) {
    std::stable_sort(
        values.begin(), values.end(),
        [](const std::string &a, const std::string &b) {
            return a.size() < b.size();
        });
    return values;
}
